<script lang="ts">
  import AppHeader from '$components/AppHeader.svelte'; import { chains } from '$lib/config/chains';
  let owner='';let chainId:number=chains[0].id;let itemsText='';let loading=false;let error='';let fetchedAt='';let nfts:Array<Record<string,unknown>>=[];
  async function loadGallery(){loading=true;error='';nfts=[];try{const items=itemsText.split('\n').map(line=>{const [contract,tokenId]=line.split(',').map(x=>x.trim());return{contract,tokenId};}).filter(x=>x.contract&&x.tokenId);const r=await fetch('/api/nfts',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({owner,chainId,items})});const data=await r.json();if(!r.ok)throw new Error(data.error);nfts=data.nfts;fetchedAt=data.fetchedAt;}catch(e){error=e instanceof Error?e.message:'NFT gallery lookup failed';}finally{loading=false;}}
  async function connect(){try{const eth=(window as unknown as {ethereum?:{request:(a:{method:string})=>Promise<string[]>}}).ethereum;if(!eth)throw new Error('Install MetaMask first.');owner=(await eth.request({method:'eth_requestAccounts'}))[0]||'';}catch(e){error=e instanceof Error?e.message:'Wallet connection failed';}}
</script>
<svelte:head><title>NFT Gallery — Poké</title></svelte:head><AppHeader active="portfolio" />
<main class="route-page discovery-page"><div class="subnav"><a href="/portfolio">← Portfolio</a><span>/</span><strong>NFT gallery</strong></div><section class="discovery-hero"><div><span class="eyebrow">OWNERSHIP VERIFICATION</span><h1>NFT gallery</h1><p>Check NFT ownership and token metadata using the collection contract and token ID.</p></div><div class="discovery-icon diamond">◇</div></section><section class="discovery-form"><div><label for="nft-owner">Wallet address</label><div class="inline-field"><input id="nft-owner" bind:value={owner} placeholder="0x wallet address"/><button onclick={connect}>Connect wallet</button></div></div><div><label for="nft-chain">Network</label><select id="nft-chain" bind:value={chainId}>{#each chains as chain}<option value={chain.id}>{chain.name}</option>{/each}</select></div><div class="full-field"><label for="nft-items">NFT contract and token ID</label><textarea id="nft-items" bind:value={itemsText} placeholder={'One NFT per line:\n0xContractAddress, 1\n0xAnotherContract, 42'}></textarea><small>Add up to 12 ERC-721 items. Poké checks ownerOf and tokenURI without fetching untrusted external metadata.</small></div>{#if error}<p class="discovery-error">{error}</p>{/if}<button class="discover-button" onclick={loadGallery} disabled={loading}>{loading?'Checking ownership…':'Build gallery'}</button></section>{#if nfts.length}<section class="discovery-results"><div class="section-head"><div><span class="eyebrow">GALLERY RESULTS</span><h2>{nfts.length} NFT{nfts.length===1?'':'s'} checked</h2></div><small>{new Date(fetchedAt).toLocaleString()}</small></div><div class="nft-grid">{#each nfts as nft}<article class:error={nft.status==='error'}><div class="nft-art"><span>{String(nft.symbol||'NFT')}</span><strong>#{String(nft.tokenId)}</strong></div><div class="nft-info"><span class:owned={nft.owned} class="ownership">{nft.status==='error'?'Lookup error':nft.owned?'Owned by wallet':'Different owner'}</span><h3>{String(nft.name||'Unknown collection')} #{String(nft.tokenId)}</h3><code>{String(nft.contract).slice(0,12)}…</code>{#if nft.tokenURI}<a href={String(nft.tokenURI)} target="_blank" rel="noreferrer">View token URI ↗</a>{/if}{#if nft.error}<p>{String(nft.error)}</p>{/if}</div></article>{/each}</div></section>{/if}</main>
